    53  bool OrfDecoder::isAppropriateDecoder(const TiffRootIFD* rootIFD,
    54                                        const Buffer* file) {
    55    const auto id = rootIFD->getID();
    56    const std::string& make = id.make;
    57
    58    // FIXME: magic
    59
    60    return make == "OLYMPUS IMAGING CORP." || make == "OLYMPUS CORPORATION" ||
    61           make == "OLYMPUS OPTICAL CO.,LTD";
    62  }
