   298  void OrfDecoder::decodeMetaDataInternal(const CameraMetaData* meta) {
   299    int iso = 0;
   300    mRaw->cfa.setCFA(iPoint2D(2,2), CFA_RED, CFA_GREEN, CFA_GREEN, CFA_BLUE);
   301
   302    if (mRootIFD->hasEntryRecursive(ISOSPEEDRATINGS))
   303      iso = mRootIFD->getEntryRecursive(ISOSPEEDRATINGS)->getU32();
   304
   305    setMetaData(meta, "", iso);
   306
   307    if (mRootIFD->hasEntryRecursive(OLYMPUSREDMULTIPLIER) &&
   308        mRootIFD->hasEntryRecursive(OLYMPUSBLUEMULTIPLIER)) {
   309      mRaw->metadata.wbCoeffs[0] = static_cast<float>(
   310          mRootIFD->getEntryRecursive(OLYMPUSREDMULTIPLIER)->getU16());
   311      mRaw->metadata.wbCoeffs[1] = 256.0F;
   312      mRaw->metadata.wbCoeffs[2] = static_cast<float>(
   313          mRootIFD->getEntryRecursive(OLYMPUSBLUEMULTIPLIER)->getU16());
   314    } else {
   315      // Newer cameras process the Image Processing SubIFD in the makernote
   316      if(mRootIFD->hasEntryRecursive(OLYMPUSIMAGEPROCESSING)) {
   317        TiffEntry *img_entry = mRootIFD->getEntryRecursive(OLYMPUSIMAGEPROCESSING);
   318        try {
   319          // get makernote ifd with containing Buffer
   320          TiffRootIFD image_processing(nullptr, img_entry->getRootIfdData(),
   321                                       img_entry->getU32());
   322
   323          // Get the WB
   324          if (image_processing.hasEntry(static_cast<TiffTag>(0x0100))) {
   325            TiffEntry* wb =
   326                image_processing.getEntry(static_cast<TiffTag>(0x0100));
   327            if (wb->count == 2 || wb->count == 4) {
   328              mRaw->metadata.wbCoeffs[0] = wb->getFloat(0);
   329              mRaw->metadata.wbCoeffs[1] = 256.0F;
   330              mRaw->metadata.wbCoeffs[2] = wb->getFloat(1);
   331            }
   332          }
   333
   334          // Get the black levels
   335          if (image_processing.hasEntry(static_cast<TiffTag>(0x0600))) {
   336            TiffEntry* blackEntry =
   337                image_processing.getEntry(static_cast<TiffTag>(0x0600));
   338            // Order is assumed to be RGGB
   339            if (blackEntry->count == 4) {
   340              for (int i = 0; i < 4; i++) {
   341                auto c = mRaw->cfa.getColorAt(i & 1, i >> 1);
   342                int j;
   343                switch (c) {
   344                case CFA_RED:
   345                  j = 0;
   346                  break;
   347                case CFA_GREEN:
   348                  j = i < 2 ? 1 : 2;
   349                  break;
   350                case CFA_BLUE:
   351                  j = 3;
   352                  break;
   353                default:
   354                  ThrowRDE("Unexpected CFA color: %u", c);
   355                }
   356
   357                mRaw->blackLevelSeparate[i] = blackEntry->getU16(j);
   358              }
   359              // Adjust whitelevel based on the read black (we assume the dynamic range is the same)
   360              mRaw->whitePoint -= (mRaw->blackLevel - mRaw->blackLevelSeparate[0]);
   361            }
   362          }
   363        } catch (TiffParserException &e) {
   364          mRaw->setError(e.what());
   365        }
   366      }
   367    }
